def priority(item: float, bins: np.ndarray) -> np.ndarray:
    rem = bins - item
    scores = np.where(rem >= 0, 1.0 / (1.0 + rem), -1.0)
    empty_mask = (bins == np.max(bins)) & (rem >= 0)
    if not np.any(bins == 0) and np.any(rem >= 0):
        first_empty_idx = np.where((bins == np.max(bins)) & (rem >= 0))[0]
        if first_empty_idx.size > 0:
            scores[first_empty_idx[0]] = max(scores) + 0.1
    return scores
